auth_pattern.imports:
import { createServerClient } from '@/lib/supabase/server';
import { currentUser } from '@clerk/nextjs/server';
import { getTenantId } from '@/lib/tenant';

function.code:
export async function getReconciliationSessions(): Promise<ReconciliationSession[]> {
  const supabase = await createServerClient();
  const tenantId = await getTenantId();

  const { data, error } = await supabase
    .from('daep_reconciliation_sessions')
    .select(`
      id,
      file_name,
      upload_date,
      total_records,
      matched_count,
      discrepancy_count,
      new_in_sis_count,
      missing_from_sis_count,
      status,
      detected_sis,
      completed_at
    `)
    .eq('tenant_id', tenantId)
    .order('upload_date', { ascending: false })
    .limit(20);

  if (error) {
    console.error('[DAEP Reconciliation] Failed to fetch sessions:', error);
    return [];
  }

  return (data || []) as ReconciliationSession[];
}

async function checkSessionCompletion(
  supabase: Awaited<ReturnType<typeof createServerClient>>,
  sessionId: string,
  tenantId: string
) {
  const { count } = await supabase
    .from('daep_reconciliation_discrepancies')
    .select('*', { count: 'exact', head: true })
    .eq('session_id', sessionId)
    .eq('resolution', 'pending')
    .neq('discrepancy_type', 'matched');

  if (count === 0) {
    await supabase
      .from('daep_reconciliation_sessions')
      .update({
        status: 'completed',
        completed_at: new Date().toISOString(),
      })
      .eq('id', sessionId)
      .eq('tenant_id', tenantId);
  }
}

export async function getSessionAuditEvents(sessionId: string): Promise<AuditEvent[]> {
  const supabase = await createServerClient();
  const tenantId = await getTenantId();

  const { data, error } = await supabase
    .from('admin_audit_log')
    .select('id, event_type, actor_email, action, details, created_at')
    .eq('tenant_id', tenantId)
    .eq('module', 'daep_management')
    .like('event_type', 'reconciliation.%')
    .or(`target_id.eq.${sessionId},details.cs.{"sessionId":"${sessionId}"}`)
    .order('created_at', { ascending: true });

  if (error) {
    console.error('[Audit] Failed to fetch session events:', error);
    return [];
  }

  return (data || []) as AuditEvent[];
}

export async function flagForLater(
  discrepancyId: string,
  note?: string
): Promise<{ success: boolean; error?: string }> {
  const supabase = await createServerClient();
  const user = await currentUser();
  const tenantId = await getTenantId();

  // ... validation ...

  // Create pending action
  const { error: insertError } = await supabase
    .from('daep_pending_actions')
    .insert({
      tenant_id: tenantId,
      created_by: user.id,
      action_type: 'reconciliation_review',
      title: `Review: ${discrepancy.student_name}`,
      description: note || `Missing from SIS - requires follow-up`,
      priority: 'normal',
      reference_type: 'discrepancy',
      reference_id: discrepancyId,
      reference_data: {
        student_id: discrepancy.student_id,
        student_name: discrepancy.student_name,
        incident_number: discrepancy.incident_number,
        discrepancy_type: discrepancy.discrepancy_type,
        daep_data: discrepancy.daep_data,
      },
    });

  // ... update discrepancy resolution ...
}

audit_logger.function_signature:
export async function logAuditEvent(entry: AuditLogEntry): Promise<void>

interface AuditLogEntry {
  eventType: AuditEventType;
  actorId: string;
  actorEmail?: string;
  actorRole?: string;
  targetId?: string;
  action: string;
  details?: Record<string, any>;
  recordSubjectName?: string;
  recordSchoolId?: string;
  tenantId?: string;
  module?: 'trespass_tracker' | 'daep_management';
}

audit_logger.usage_example:
await logAuditEvent({
  eventType: 'reconciliation.reminder_sent',
  module: 'daep_management',
  actorId: 'system',
  actorEmail: 'system@cron',
  targetId: sessionId,
  action: 'Sent daily reminder for incomplete session',
  details: {
    sessionId,
    fileName: session.file_name,
  },
  tenantId: session.tenant_id,
});

existing_types.type:
export interface ReconciliationSession {
  id: string;
  file_name: string;
  upload_date: string;
  total_records: number;
  matched_count: number;
  discrepancy_count: number;
  new_in_sis_count: number;
  missing_from_sis_count: number;
  status: ReconciliationStatus;
  detected_sis: string | null;
  completed_at: string | null;
}

export interface ReconciliationSummary {
  sessionId: string;
  fileName: string;
  uploadDate: string;
  completedAt: string;
  completedBy: string;
  completedByEmail: string;
  durationFormatted: string;
  totalRecords: number;
  matchedCount: number;
  conflictCount: number;
  newInSISCount: number;
  missingFromSISCount: number;
  acceptedSISCount: number;
  keptDAEPCount: number;
  newPlacementsCreated: number;
  missingReviewed: number;
  resolutions: ResolutionDetail[];
  matchedRecords: MatchedRecordSummary[];
}

new_types.type:
export interface UnresolvedSession {
  id: string;
  fileName: string;
  uploadDate: string;
  unresolvedCount: number;
  totalDiscrepancies: number;
  status: string;
  ageCategory: SessionAgeCategory;
}

export interface ReconciliationPendingAction {
  id: string;
  type: 'reconciliation_incomplete' | 'reconciliation_abandoned';
  title: string;           // "Reconciliation incomplete" or "Reconciliation abandoned"
  description: string;     // File name
  subtitle: string;        // "5 of 7 unresolved • 3 days ago"
  actionUrl: string;       // /daep/reconciliation/{sessionId}
  ageCategory: SessionAgeCategory;
  createdAt: string;
}

